:root {
  /* Colors */
  --color-concrete-canvas: #f5f5f5;
  --color-mist-surface: #fafafa;
  --color-paper: #ffffff;
  --color-quartz-tag: #f4f4f5;
  --color-fog-wash: #0000000d;
  --color-ink: #221f1c;
  --color-pebble-caption: #797267;
  --color-ash-hairline: #00000014;
  --color-stone-border: #0000001f;
  --color-cobalt-pulse: #518bdb;
  --color-amber-spark: #e5a057;
  --color-ember-dot: #f92d4e;

  /* Typography — Font Families */
  --font-haffer: "Haffer", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-perfectly-nineties: "perfectlyNineties", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 2.4;
  --tracking-small: 2.2px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.556;
  --tracking-body-lg: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.333;
  --tracking-heading-sm: 0px;
  --text-heading: 28px;
  --leading-heading: 1.25;
  --tracking-heading: 0px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: 0.96px;
  --text-display: 64px;
  --leading-display: 1.125;
  --tracking-display: -1.6px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-black: 900;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-128: 128px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1152px;
  --layout-lede-width: 672px;
  --layout-section-gap: 128px;
  --layout-card-padding: 16px;
  --layout-element-gap: 12px;
  --layout-nav-height: 68px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 14px;
  --radius-2xl: 18px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 4px;
  --radius-tags: 4px;
  --radius-nav: 8px;
  --radius-images: 8px;
  --radius-small-cards: 8px;
  --radius-buttons: 10px;
  --radius-inputs: 10px;
  --radius-alert-banners: 10px;
  --radius-cards: 14px;
  --radius-sections: 18px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-subtle-2: inset 0 -2px 0 0 rgba(0, 0, 0, 0.2);
  --shadow-sm: 0 0 0 1px rgba(34, 31, 28, 0.065), 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 0 0 1px rgba(34, 31, 28, 0.065), 0 25px 50px -12px rgba(0, 0, 0, 0.18);

  /* Surfaces */
  --surface-concrete-canvas: #f5f5f5;
  --surface-mist-surface: #fafafa;
  --surface-paper: #ffffff;
  --surface-ink: #221f1c;
}

